        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]
    return "\n".join(lines) + "\n"


def render_csv(table):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(table.columns)
    writer.writerows(table.rows)
    return out.getvalue()


def render_json(table):
    return json.dumps(table.dicts(), ensure_ascii=False) + "\n"


RENDERERS = {"text": render_text, "csv": render_csv, "json": render_json}


def render(table, fmt="text"):
    return RENDERERS[fmt](table)


# --- transforms: one small function each, `name` or `name:ARG` in `apply` ----------------------------------------

    "ge": t_ge,
}


def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage, at_least=False):
    if len(args) < count or (len(args) > count and not at_least):
        raise UsageError("usage: %s %s" % (PROG, usage))


def _row_error(table, number, message):
    """The TabulaError `FILE: row N: message`; N counts the data rows of the file from 1, in file order."""
    return TabulaError("%s: row %d: %s" % (table.source, number, message))


def _cell_number(table, number, column, value):
    """The Decimal a cell holds; a cell that is not a number is a mistake naming the row and the column."""
    try:
        return _need_number(value)
    except TabulaError as exc:
        raise _row_error(table, number, "column %r: %s" % (column, exc))


def _column_numbers(table, columns, skip_blank=False):
    """{position: [Decimal per row]} for the named columns, checked row by row in file order.

    With skip_blank, an empty (or whitespace-only) cell gives None instead of a mistake."""
    columns = list(dict.fromkeys(columns))
    positions = [table.index(name) for name in columns]
    found = {at: [] for at in positions}
    for number, row in enumerate(table.rows, 1):
        for name, at in zip(columns, positions):
            blank = skip_blank and not row[at].strip()
            found[at].append(None if blank else _cell_number(table, number, name, row[at]))
    return found


def _sum(numbers):
    with _wide(numbers):
        return sum(numbers, Decimal(0))


def _mean(numbers):
    with _wide(numbers, 10 + len(str(len(numbers)))):
        return _sum(numbers) / len(numbers)


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_args(args, 3, "apply FILE COLUMN TRANSFORM...", at_least=True)
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise _row_error(table, number, exc)
        rows.append(row)
    return table.with_rows(rows)


SORT_MODS = ("num", "desc")


def _sort_key(text):
    """(column, numeric, descending) from `NAME[:num][:desc]`; a bad key is a usage error."""
    name, *mods = text.split(":")
    if not name:
        raise UsageError("sort: no column name in key %r" % text)
    for mod in mods:
        if mod not in SORT_MODS:
            raise UsageError("sort: unknown modifier %r in key %r (use num or desc)" % (mod, text))
    if len(set(mods)) != len(mods):
        raise UsageError("sort: modifier repeated in key %r" % text)
    return name, "num" in mods, "desc" in mods


def cmd_sort(args, opts):
    _need_args(args, 2, "sort FILE KEY...", at_least=True)
    keys = [_sort_key(k) for k in args[1:]]
    table = load(args[0])
    for name, _, _ in keys:
        table.index(name)
    numbers = _column_numbers(table, [name for name, num, _ in keys if num])
    order = list(range(len(table)))
    for name, num, desc in reversed(keys):
        values = numbers[table.index(name)] if num else table.column(name)
        order.sort(key=values.__getitem__, reverse=desc)
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPS = ("==", "!=", ">=", "<=", ">", "<", "~")
COMPARE = {
    "==": lambda a, b: a == b, "!=": lambda a, b: a != b, ">=": lambda a, b: a >= b,
    "<=": lambda a, b: a <= b, ">": lambda a, b: a > b, "<": lambda a, b: a < b,
}


def _condition(text):
    """(column, operator, value) from `COLUMNOPVALUE`: the earliest operator, the longest where two start together."""
    found = [(text.find(op), -len(op), op) for op in FILTER_OPS if op in text]
    if not found:
        raise UsageError("filter: no operator in condition %r (use one of %s)" % (text, " ".join(FILTER_OPS)))
    at, _, op = min(found)
    if at == 0:
        raise UsageError("filter: no column name in condition %r" % text)
    return text[:at], op, text[at + len(op):]


def _holds(cell, op, value):
    if op == "~":
        return t_icontains(cell, value) == "yes"
    left, right = to_decimal(cell), to_decimal(value)
    if left is not None and right is not None:
        return COMPARE[op](left, right)
    return COMPARE[op](cell, value)


def cmd_filter(args, opts):
    _need_args(args, 2, "filter FILE CONDITION...", at_least=True)
    conditions = [_condition(c) for c in args[1:]]
    table = load(args[0])
    wanted = [(table.index(name), op, value) for name, op, value in conditions]
    return table.with_rows([row for row in table.rows if all(_holds(row[at], op, v) for at, op, v in wanted)])


AGGREGATES = ("sum", "min", "max", "mean")


def _aggregate(text):
    """(function, column) from `count` or `FUNCTION:COLUMN`; anything else is a usage error."""
    name, colon, column = text.partition(":")
    if text == "count" or (name in AGGREGATES and column):
        return name, column
    raise UsageError("group: %r is not an aggregate (count, sum:COLUMN, min:COLUMN, max:COLUMN, mean:COLUMN)" % text)


def _aggregated(name, numbers, count):
    if name == "count":
        return str(count)
    if name == "sum":
        return fmt_decimal(_sum(numbers))
    if name == "mean":
        return fmt_2dp(_mean(numbers))
    return fmt_decimal(min(numbers) if name == "min" else max(numbers))


def cmd_group(args, opts):
    _need_args(args, 3, "group FILE BY AGGREGATE...", at_least=True)
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: an aggregate is given twice")
    aggregates = [_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    columns = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    for name in columns[1:]:
        if name == args[1]:
            raise TabulaError("group: column %r would appear twice" % name)
    numbers = _column_numbers(table, [c for n, c in aggregates if n != "count"])
    groups = {}
    for i, row in enumerate(table.rows):
        groups.setdefault(row[by], []).append(i)
    rows = []
    for key, members in groups.items():
        out = [key]
        for name, column in aggregates:
            values = [] if name == "count" else [numbers[table.index(column)][i] for i in members]
            out.append(_aggregated(name, values, len(members)))
        rows.append(out)
    return Table(columns, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    lat, rat = left.index(args[2]), right.index(args[2])
    keep = [i for i in range(len(right.columns)) if i != rat]
    columns = left.columns + [right.columns[i] + ("_right" if right.columns[i] in left.columns else "") for i in keep]
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("join: column %r would appear twice" % name)
    matches = {}
    for row in right.rows:
        matches.setdefault(row[rat], []).append([row[i] for i in keep])
    rows = []
    for row in left.rows:
        for other in matches.get(row[lat]) or ([[""] * len(keep)] if opts["kind"] == "left" else []):
            rows.append(row + other)
    return Table(columns, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_col, at_val = table.index(args[1]), table.index(args[2]), table.index(args[3])
    rows, heads, cells = {}, {}, {}
    for number, row in enumerate(table.rows, 1):
        head = row[at_col]
        if not head.strip():
            raise _row_error(table, number, "column %r: empty value" % args[2])
        if head == args[1]:
            raise _row_error(table, number, "column %r: value %r is the name of the row column" % (args[2], head))
        amount = _cell_number(table, number, args[3], row[at_val])
        rows.setdefault(row[at_row], None)
        heads.setdefault(head, None)
        cells.setdefault((row[at_row], head), []).append(amount)
    out = [[r] + [fmt_decimal(_sum(cells[(r, h)])) if (r, h) in cells else "0" for h in heads] for r in rows]
    return Table([args[1]] + list(heads), out, table.source)


def cmd_dedupe(args, opts):
    _need_args(args, 2, "dedupe FILE KEY...", at_least=True)
    table = load(args[0])
    at = [table.index(name) for name in args[1:]]
    chosen = {}
    for i, row in enumerate(table.rows):
        key = tuple(row[a] for a in at)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = i
    return table.with_rows([table.rows[i] for i in sorted(chosen.values())])


def _median(numbers):
    middle = len(numbers) // 2
    if len(numbers) % 2:
        return numbers[middle]
    return _mean(numbers[middle - 1:middle + 1])


def cmd_stats(args, opts):
    _need_args(args, 2, "stats FILE COLUMN...", at_least=True)
    table = load(args[0])
    found = _column_numbers(table, args[1:], skip_blank=True)
    rows = []
    for name in args[1:]:
        numbers = sorted(n for n in found[table.index(name)] if n is not None)
        if not numbers:
            rows.append([name, "0", "", "", "", ""])
        else:
            rows.append([name, str(len(numbers)), fmt_decimal(numbers[0]), fmt_decimal(numbers[-1]),
                         fmt_2dp(_mean(numbers)), fmt_2dp(_median(numbers))])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "sort rows by one or more keys (NAME[:num][:desc])"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "keep rows where every condition holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value with count, sum, min, max, mean"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "join two files on a column (--kind inner|left)"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "COLUMN values become columns of sums"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop duplicate rows (--keep first|last)"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median per column"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = dict(DEFAULTS), [], 0
    while i < len(argv):
        arg = argv[i]
        name, equals, value = arg[2:].partition("=")
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif arg.startswith("--") and name in OPTIONS:
            if not equals:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def _drop_stdout():
    """After a failed write, point stdout at /dev/null so the flush at exit cannot fail again."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError):
        pass


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except OSError as exc:
        if not isinstance(exc, BrokenPipeError):
            print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        _drop_stdout()
        return 0 if isinstance(exc, BrokenPipeError) else 1
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1

